# is_pangram :: 'The quick brown fox jumps over the lazy dog'
import string

def is_pangram(s):
    return set(string.ascii_lowercase).issubset(s.lower())

if __name__ == '__main__':
    print(is_pangram('The quick brown fox jumps over the lazy dog'))

